import {
    Table,
    IntegerColumn,
    StringColumn,
    DomainPathColumn,
    TableNameColumn,
    BooleanColumn,
    ReferenceColumn,
    DomainIdColumn,
    UserRolesColumn,
    ConditionsColumn,
    TranslatedFieldColumn,
} from '../../db'

export const sys_ui_module = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    audit: true,
    extends: 'sys_metadata',
    label: 'Module',
    name: 'sys_ui_module',
    schema: {
        order: IntegerColumn({
            label: 'Order',
        }),
        path: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Path',
            maxLength: 3500,
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
        table: TableNameColumn({
            attributes: {
                allow_public: true,
                base_start: true,
            },
            label: 'Table',
            tableReference: true,
        }),
        view_name: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            default:
                "javascript:var viewDefault='';if(typeof parent != 'undefined')if(parent.device_type=='mobile') viewDefault='Mobile';viewDefault",
            label: 'View name',
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        application: ReferenceColumn({
            attributes: {
                allow_invalid: true,
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'The navigation menu where this module should reside',
                    label: 'Application menu',
                    plural: 'Application menus',
                },
            ],
            referenceTable: 'sys_ui_application',
            dynamicCreation: true,
            dynamicCreationScript: 'var mmc = new MobileMenuCreator(current, value); mmc.create(true);',
        }),

        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the script belongs',
                    label: 'Domain',
                    plural: 'Domains',
                },
            ],
        }),
        roles: UserRolesColumn({
            array: true,
            attributes: {
                no_truncate: true,
                record_watcher_blacklist: true,
            },
            label: 'Roles',
        }),
        path_relative_to_root: BooleanColumn({
            default: false,
            label: 'Path Relative To Root',
        }),
        filter: ConditionsColumn({
            dependent: 'table',
            label: 'Filter',
            maxLength: 3500,
        }),
        name: TranslatedFieldColumn({
            label: [
                {
                    hint: 'For references by menu lists',
                    label: 'Name',
                    plural: 'Names',
                },
            ],
            maxLength: 80,
        }),
        uncancelable: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'If this module is clicked, then another module is clicked, Setting this to true will prevent this module from being canceled.',
                    label: 'Uncancelable by Other Modules',
                    plural: 'Uncancelable by Other Modules',
                },
            ],
        }),
    },
    textIndex: true,
})
